mapper.select:
SELECT COUNT(*) FROM boarding_order
WHERE room_id = #{roomId}
  AND status IN ('BOOKED', 'CHECKED_IN')
  AND id != COALESCE(#{excludeId}, -1)
  AND start_at < #{end}
  AND (COALESCE(end_at, planned_end_on || ' 23:59')) > #{startAt}

mapper.update:
UPDATE boarding_order SET status = 'CHECKED_OUT', end_at = #{endAt},
       days = #{days}, bill_id = #{billId}
WHERE id = #{id} AND status = 'CHECKED_IN'
